python3 - <<'PY'
import json
from pathlib import Path
j=json.loads(Path('benchmark/source_data.json').read_text())
rows=j['national_development']['data']
dims=j['national_development']['dimensions']
mins={d:1e18 for d in dims}
maxs={d:-1e18 for d in dims}
for r in rows:
  for d in dims:
    v=r[d]
    mins[d]=min(mins[d],v)
    maxs[d]=max(maxs[d],v)

def norm(d,v):
  return 100*(v-mins[d])/(maxs[d]-mins[d])
# Compute z distance from group mean in normalized space
from collections import defaultdict
import math
by=defaultdict(list)
for r in rows:
  by[r['income_group']].append(r)
means={}
for g,rs in by.items():
  m={d:0 for d in dims}
  for r in rs:
    for d in dims:
      m[d]+=norm(d,r[d])
  for d in dims:
    m[d]/=len(rs)
  means[g]=m

out=[]
for r in rows:
  g=r['income_group']
  dist=0
  for d in dims:
    dv=norm(d,r[d])-means[g][d]
    dist+=dv*dv
  out.append((math.sqrt(dist), r['country'], g))
for dist,c,g in sorted(out, reverse=True)[:10]:
  print(f"{c:20} {g:12} dist={dist:.1f}")
PY

